:root {
  --ink: #26343b;
  --paper: #fffdf7;
  --line: #d9d1c2;
  --muted: #687379;
  --pale: #eef3ef;
  --gold: #e6b64c;
  --rust: #b85b3e;
  --sky: #d9ebef;
}

.meteorite-card {
  box-sizing: border-box;
  width: 480px;
  padding: 14px 16px;
  display: flex;
  flex-direction: column;
  gap: 10px;
  color: var(--ink);
  background: var(--paper);
  border: 2px solid var(--ink);
  border-radius: 18px;
}

.case-header {
  display: flex;
  align-items: center;
  gap: 10px;
}

.case-mark {
  width: 34px;
  height: 34px;
  display: grid;
  place-items: center;
  color: var(--paper);
  background: var(--ink);
  border-radius: 10px;
  font-size: 12px;
  font-weight: 800;
  letter-spacing: 0.08em;
}

.case-heading {
  flex: 1;
}

.eyebrow,
.case-date,
.sample-detail,
.metric-label,
.reviewer {
  margin: 0;
  color: var(--muted);
  font-size: 11px;
  line-height: 1.25;
}

.eyebrow {
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.case-title {
  margin: 1px 0;
  font-size: 20px;
  line-height: 1.05;
  letter-spacing: -0.03em;
}

.status-pill {
  padding: 5px 8px;
  color: var(--rust);
  background: var(--sky);
  border-radius: 999px;
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.06em;
}

.sample-summary {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 9px 10px;
  background: var(--pale);
  border: 1px solid var(--line);
  border-radius: 12px;
}

.specimen-mark {
  width: 38px;
  height: 38px;
  margin: 0;
  display: grid;
  place-items: center;
  color: var(--gold);
  background: var(--ink);
  border-radius: 50%;
  font-size: 20px;
}

.sample-copy {
  flex: 1;
}

.sample-name {
  margin: 0 0 2px;
  font-size: 14px;
  font-weight: 800;
}

.tray-code {
  padding: 4px 7px;
  border: 1px solid var(--line);
  border-radius: 6px;
  color: var(--ink);
  background: var(--paper);
  font-size: 11px;
  font-weight: 800;
}

.metrics {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  border: 1px solid var(--line);
  border-radius: 10px;
  overflow: hidden;
}

.metric {
  padding: 7px 10px;
  display: flex;
  flex-direction: column;
  gap: 2px;
  border-right: 1px solid var(--line);
}

.metric:last-child {
  border-right: 0;
}

.metric-value {
  font-size: 14px;
  line-height: 1.15;
}

.review-note {
  display: flex;
  align-items: center;
  gap: 7px;
  padding: 7px 9px;
  color: var(--ink);
  background: var(--sky);
  border-radius: 8px;
  font-size: 12px;
  line-height: 1.25;
}

.review-note p {
  margin: 0;
}

.note-dot {
  width: 7px;
  height: 7px;
  flex: 0 0 auto;
  background: var(--rust);
  border-radius: 50%;
}

.case-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.archive-button {
  padding: 7px 10px;
  color: var(--paper);
  background: var(--rust);
  border: 0;
  border-radius: 8px;
  font-size: 12px;
  font-weight: 800;
}
